[
  {
    "name": "宫门外·雪道",
    "description": "沈清辞入宫的第一道关卡，长长的青石御道",
    "visualStyle": "鹅毛大雪纷飞，红墙金瓦隐于雪雾，远处宫门如巨兽蹲伏，画面冷寂苍凉"
  },
  {
    "name": "掖庭大殿",
    "description": "册封选秀的礼仪大殿",
    "visualStyle": "殿内烛火千盏，金砖漫地，藻井绘青龙，香烟袅袅，极尽奢华"
  },
  {
    "name": "冷宫·梧桐院",
    "description": "沈清辞被安排居住的偏僻院落",
    "visualStyle": "院中一株老梧桐，落叶铺地，苔痕上阶，蛛网尘封，月光清冷"
  },
  {
    "name": "长信宫·贵妃寝殿",
    "description": "萧贵妃的主殿",
    "visualStyle": "红烛高烧，帷幔重重，熏香浓郁，色调以正红与鎏金为主，富贵逼人"
  },
  {
    "name": "御书房",
    "description": "皇帝处理政务之所",
    "visualStyle": "书架万卷，烛光摇曳，窗外竹影婆娑，色调沉郁"
  },
  {
    "name": "太液池畔",
    "description": "后宫散步的湖畔长廊",
    "visualStyle": "池水如镜，荷花残败，雾气氤氲，远处亭台楼阁隐于烟波"
  }
]
